function setBusy(busy, stepLabel, pct) {
  document.getElementById("btn-iterate").disabled = busy;
  document.getElementById("btn-reset").disabled = busy;
  document.getElementById("progress-wrap").style.display = busy ? "block" : "none";

  const bar = document.getElementById("progress-bar");
  const label = document.getElementById("progress-label");

  if (!busy) {
    label.textContent = "";
    return;
  }

  if (pct === null || pct === undefined) {
    // pas de % applicable pour cette etape (ingestion, export STL...)
    bar.classList.add("indeterminate");
    bar.style.width = "";
    label.textContent = stepLabel || "calcul en cours...";
  } else {
    bar.classList.remove("indeterminate");
    bar.style.width = pct + "%";
    label.innerHTML = `${stepLabel || "calcul en cours"} -- <span id="progress-pct">${pct}%</span>`;
  }
}

